XplorMRParser::XplorMRParser(TokenStream *input) : XplorMRParser(input, antlr4::atn::ParserATNSimulatorOptions()) {}

XplorMRParser::XplorMRParser(TokenStream *input, const antlr4::atn::ParserATNSimulatorOptions &options) : Parser(input) {
  XplorMRParser::initialize();
  _interpreter = new atn::ParserATNSimulator(this, *xplormrparserParserStaticData->atn, xplormrparserParserStaticData->decisionToDFA, xplormrparserParserStaticData->sharedContextCache, options);
}

XplorMRParser::~XplorMRParser() {
  delete _interpreter;
}

const atn::ATN& XplorMRParser::getATN() const {
  return *xplormrparserParserStaticData->atn;
}

